using AshkanCMS.Data; using AshkanCMS.Models; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace AshkanCMS.Controllers;
public class HomeController(AppDbContext db):Controller{public async Task<IActionResult> Index(){return View(await db.Posts.Include(x=>x.Category).Where(x=>x.Status==ContentStatus.Published).OrderByDescending(x=>x.PublishedAt).ToListAsync());} public async Task<IActionResult> Post(string id){var p=await db.Posts.Include(x=>x.Category).FirstOrDefaultAsync(x=>x.Slug==id&&x.Status==ContentStatus.Published); if(p==null)return NotFound(); p.Views++; await db.SaveChangesAsync(); return View(p);} public async Task<IActionResult> Page(string id){var p=await db.Pages.FirstOrDefaultAsync(x=>x.Slug==id&&x.Status==ContentStatus.Published); return p==null?NotFound():View(p);} public IActionResult Error()=>View();}
